def counted(f):
def wrapped(*args, **kwargs):
wrapped.calls += 1
return f(*args, **kwargs)
wrapped.calls = 0
return wrapped
@counted
def foo():
print('1')
foo()
foo()
foo()
foo()
foo()
foo()
print(foo.calls)

